(() => {
'use strict';
const STORAGE_KEY = 'ramon_orcamentos_v1';
const DEFAULT_CONDITIONS = 'Orçamento sujeito a revisão caso sejam identificados danos adicionais após desmontagem, mediante aprovação do cliente.';
const GROUPS = [
 {name:'Frente', parts:[['capo','Capô'],['parachoque-dianteiro','Para-choque dianteiro'],['painel-dianteiro','Painel dianteiro'],['paralama-dianteiro-esq','Para-lama dianteiro esquerdo'],['paralama-dianteiro-dir','Para-lama dianteiro direito']]},
 {name:'Laterais', parts:[['porta-dianteira-esq','Porta dianteira esquerda'],['porta-traseira-esq','Porta traseira esquerda'],['porta-dianteira-dir','Porta dianteira direita'],['porta-traseira-dir','Porta traseira direita'],['caixa-ar-esq','Caixa de ar esquerda (LE)'],['caixa-ar-dir','Caixa de ar direita (LD)']]},
 {name:'Traseira', parts:[['tampa-portamalas','Tampa do porta-malas'],['parachoque-traseiro','Para-choque traseiro'],['painel-traseiro','Painel traseiro']]},
 {name:'Parte superior', parts:[['teto','Teto']]},
 {name:'Outras peças frequentes', parts:[['retrovisor-esq','Retrovisor esquerdo'],['retrovisor-dir','Retrovisor direito'],['soleira','Soleira'],['coluna','Coluna'],['grade-dianteira','Grade dianteira'],['farol','Farol / lanterna']]}
];
const INTERVENTIONS = ['Lanternagem','Preparação','Pintura','Retoque','Polimento','Substituição','Desmontagem / montagem','Outro'];
const PAYMENT_TYPES = ['Pix','Dinheiro','Cartão de débito','Cartão de crédito','Transferência','Outro'];
const app = document.querySelector('#app');
const modalRoot = document.querySelector('#modal-root');
const formatBRL = new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
const formatNumber = new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
let screen = 'home';
let step = 1;
let searchParts = '';
let historyFilter = '';
let savingError = false;
let toastTimer = null;
let store = loadStore();
const PHOTO_LIMIT=10, PHOTO_FILE_MAX=15*1024*1024;
const PHOTO_DB='ramon_orcamentos_fotos_v1';
let photoRenderToken=0;
let activePhotoURLs=[];
function defaults(){return {name:'Ramon Retoques Automotivos',responsible:'Ramon e Valtinho',phone:'(31) 98430-8475',address:'Rua Passarela, 72 — Bairro Cruzeiro Celeste — João Monlevade/MG',validDays:30,conditions:DEFAULT_CONDITIONS,footer:'Tudo posso Naquele que me fortalece',logo:null};}
function loadStore(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&parsed.version===1&&Array.isArray(parsed.quotes))return {...parsed,config:{...defaults(),...(parsed.config||{})},counter:Number(parsed.counter)||0};}}catch(e){console.warn('Dados locais não disponíveis.');}return {version:1,counter:0,config:defaults(),quotes:[],activeId:null};}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(store));savingError=false;}catch(e){savingError=true;notify('Falha ao salvar neste navegador. Exporte um backup ou libere espaço.');}}
// Fotos ficam no IndexedDB (fora do localStorage), para preservar os orçamentos existentes.
function openPhotoDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(new Error('Armazenamento de fotos indisponível'));return;}const req=indexedDB.open(PHOTO_DB,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('images'))req.result.createObjectStore('images',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('Banco de fotos inacessível'));});}
async function photoTransaction(mode,operation){const db=await openPhotoDB();return new Promise((resolve,reject)=>{let value;const tx=db.transaction('images',mode),os=tx.objectStore('images');try{value=operation(os);}catch(err){tx.abort();db.close();reject(err);return;}tx.oncomplete=()=>{db.close();resolve(value)};tx.onerror=()=>{db.close();reject(tx.error||new Error('Falha no banco de fotos'));};tx.onabort=()=>{db.close();reject(tx.error||new Error('Operação de fotos cancelada'));};});}
async function savePhotoFile(record){return photoTransaction('readwrite',os=>os.put(record));}
async function getPhotoFile(id){const db=await openPhotoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('images','readonly');const req=tx.objectStore('images').get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();reject(tx.error)};});}
async function deletePhotoFile(id){return photoTransaction('readwrite',os=>os.delete(id));}
async function replacePhotoFiles(records){return photoTransaction('readwrite',os=>{os.clear();records.forEach(record=>os.put(record));});}
function photoList(q){return Array.isArray(q?.photos)?q.photos:[];}
function photoCards(q){const photos=photoList(q);return `<div class="photo-grid" id="vehicle-photo-list">${photos.map((p,index)=>`<div class="photo-card"><div class="photo-preview"><img data-photo-image="${E(p.id)}" alt="Foto ${index+1} do veículo" loading="lazy"></div><div class="photo-card-foot"><span>Foto ${index+1}</span><button type="button" data-action="photo-remove" data-id="${E(p.id)}" aria-label="Remover foto ${index+1}">Remover</button></div></div>`).join('')}</div>`;}
function photoSection(q){const count=photoList(q).length;return `<div class="field span2 vehicle-photo-section"><label>Fotos do veículo <span class="optional-photo-label">(opcional)</span></label><p class="photo-hint">Registre avarias ou o estado do veículo. Até ${PHOTO_LIMIT} fotos.</p>${photoCards(q)}<div class="photo-actions"><label class="btn btn-secondary photo-add ${count>=PHOTO_LIMIT?'photo-disabled':''}" for="vehicle-photo-gallery">Inserir fotos</label><input id="vehicle-photo-gallery" class="file-hidden" type="file" accept="image/*" multiple ${count>=PHOTO_LIMIT?'disabled':''}></div><label class="photo-pdf-choice"><input type="checkbox" data-include-photos ${q.includePhotosInPdf?'checked':''}><span><strong>Incluir fotos no PDF</strong><small>${q.includePhotosInPdf?'Fotos serão acrescentadas ao final do PDF.':'Deixar desmarcado para enviar apenas o orçamento.'}</small></span></label><p class="photo-note">Fotos armazenadas somente neste navegador. Elas entram no backup com o restante do orçamento. Quando incluídas no PDF, podem gerar páginas adicionais.</p></div>`;}
function releasePhotoURLs(){activePhotoURLs.forEach(url=>URL.revokeObjectURL(url));activePhotoURLs=[];}
async function hydratePhotoCards(){const token=++photoRenderToken;releasePhotoURLs();const images=[...app.querySelectorAll('[data-photo-image]')];await Promise.all(images.map(async img=>{try{const record=await getPhotoFile(img.dataset.photoImage);if(!record?.blob||token!==photoRenderToken||!img.isConnected)return;const url=URL.createObjectURL(record.blob);activePhotoURLs.push(url);img.src=url;}catch{if(token===photoRenderToken&&img.isConnected)img.alt='Foto indisponível neste aparelho';}}));}
function refreshPhotoSection(q){const panel=app.querySelector('.vehicle-photo-section');if(!panel)return;const replacement=document.createElement('div');replacement.innerHTML=photoSection(q);panel.replaceWith(replacement.firstElementChild);hydratePhotoCards();}
async function compressVehiclePhoto(file){if(!file.type.startsWith('image/'))throw new Error('Selecione uma foto válida.');if(file.size>PHOTO_FILE_MAX)throw new Error('Foto muito grande: limite de 15 MB por arquivo.');const url=URL.createObjectURL(file);let img;try{img=await new Promise((resolve,reject)=>{const picture=new Image();picture.onload=()=>resolve(picture);picture.onerror=()=>reject(new Error('Não foi possível abrir esta imagem.'));picture.src=url;});const scale=Math.min(1,1400/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Não foi possível processar a foto.');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.73));if(!blob)throw new Error('Falha ao comprimir a foto.');return {blob,width:canvas.width,height:canvas.height};}finally{URL.revokeObjectURL(url);}}
async function addVehiclePhotos(files,q){const validFiles=Array.from(files||[]);if(!validFiles.length)return;let succeeded=0;let reason='';for(const file of validFiles){if(photoList(q).length>=PHOTO_LIMIT){reason=`Limite de ${PHOTO_LIMIT} fotos por orçamento.`;break;}try{const photo=await compressVehiclePhoto(file);const id='p-'+Date.now()+'-'+Math.random().toString(36).slice(2,12);await savePhotoFile({id,quoteId:q.id,blob:photo.blob,width:photo.width,height:photo.height,name:file.name.slice(0,100)});if(!Array.isArray(q.photos))q.photos=[];q.photos.push({id,name:file.name.slice(0,100)});touch(q);succeeded++;}catch(err){reason=err.message||'Falha ao salvar a foto';}}
if(screen==='editor'&&step===1&&store.activeId===q.id)refreshPhotoSection(q);notify(succeeded?`${succeeded} foto(s) adicionada(s) e salva(s).${reason?' '+reason:''}`:reason||'Não foi possível salvar a foto.');}
function blobAsDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
function dataURLToBlob(src){if(typeof src!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(src)||src.length>3200000)throw new Error('Imagem de backup inválida');const bytes=atob(src.split(',')[1]),array=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)array[i]=bytes.charCodeAt(i);return new Blob([array],{type:'image/jpeg'});}
function nowISO(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function prettyDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(s||'')))return '—';const [y,m,d]=s.split('-');return `${d}/${m}/${y}`;}
function plusDays(date,days){const d=new Date((/^\d{4}-\d{2}-\d{2}$/.test(date)?date:nowISO())+'T12:00:00');d.setDate(d.getDate()+Number(days||0));return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function E(x){return String(x==null?'':x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function I(name){return `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;}
function money(cents){return cents===null||cents===undefined?'A definir':formatBRL.format(cents/100);}
function valueOrDash(cents){return cents===null||cents===undefined?'—':money(cents);}
function editMoney(cents){return cents===null||cents===undefined?'':formatNumber.format(cents/100);}
function parseMoney(s){let txt=String(s??'').trim().replace(/R\$/gi,'').replace(/\s/g,'');if(!txt)return null;if(!/^[\d.,]+$/.test(txt))return null;if(txt.includes(',')){txt=txt.replace(/\./g,'').replace(',','.');}else if(/^\d{1,3}(\.\d{3})+$/.test(txt)){txt=txt.replace(/\./g,'');}else if(/^\d+\.\d{1,2}$/.test(txt)){}else{txt=txt.replace(/\./g,'');}const n=Number(txt);if(!Number.isFinite(n)||n<0||n>100000000)return null;return Math.round(n*100);}
function toDigits(value){return String(value||'').replace(/\D/g,'');}
function phoneMask(s){const d=toDigits(s).slice(0,11);if(d.length<3)return d?`(${d}`:'';if(d.length<=6)return `(${d.slice(0,2)}) ${d.slice(2)}`;if(d.length<=10)return `(${d.slice(0,2)}) ${d.slice(2,6)}-${d.slice(6)}`;return `(${d.slice(0,2)}) ${d.slice(2,7)}-${d.slice(7)}`;}
function makeItem(id,name,custom=false){return {id,name,custom,selected:false,interventions:[],description:'',manualDescription:false,service:null,material:null,noMaterial:false,observation:''};}
function newQuote(){store.counter+=1;const day=nowISO(),year=day.slice(0,4),id='q-'+Date.now()+'-'+Math.random().toString(36).slice(2,9);const items=GROUPS.flatMap(g=>g.parts.map(p=>makeItem(p[0],p[1])));const quote={id,code:`RAM-${year}-${String(store.counter).padStart(4,'0')}`,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),status:'draft',date:day,client:'',phone:'',address:'',document:'',vehicle:'',plate:'',color:'',year:'',vehicleNote:'',evaluator:'',photos:[],includePhotosInPdf:false,items,extras:[],discount:null,payments:[],cashValue:null,installmentValue:null,paymentDetails:'',delivery:'',validDays:store.config.validDays,conditions:store.config.conditions,paymentReviewed:false};store.quotes.unshift(quote);store.activeId=id;persist();return quote;}
function activeQuote(create=true){let q=store.quotes.find(q=>q.id===store.activeId);if(!q&&create)q=newQuote();return q;}
function touch(q){q.updatedAt=new Date().toISOString();if(q.status!=='draft')q.status='draft';persist();}
function getSelected(q){return (q.items||[]).filter(x=>x.selected);}
function sums(q){let services=0,materials=0,extras=0,pending=0;for(const i of getSelected(q)){if(i.service==null)pending++;else services+=i.service;if(i.material==null&&!i.noMaterial)pending++;else materials+=Number(i.material||0);}for(const i of q.extras||[]){if(i.value==null)pending++;else extras+=i.value;}const discount=Number(q.discount||0);const subtotal=services+materials+extras;return {services,materials,extras,discount,subtotal,total:subtotal-discount,pending,invalid:discount>subtotal,items:getSelected(q).length+(q.extras||[]).length};}
function statusText(q){const s=sums(q);return q.status==='draft'?'Rascunho':s.pending?'Preliminar':'Pronto';}
function statusHTML(q){const val=statusText(q),css=val==='Pronto'?'ready':val==='Preliminar'?'prelim':'draft';return `<span class="status status-${css}"><span class="dot"></span>${val}</span>`;}
function notify(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3800);}
function confirmDialog(title,message,confirmText,onConfirm,danger=false){modalRoot.innerHTML=`<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${E(title)}</h2><p>${E(message)}</p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-modal="cancelar">Cancelar</button><button type="button" class="btn ${danger?'btn-danger':'btn-primary'}" data-modal="confirmar">${E(confirmText)}</button></div></div></div>`;const fn=e=>{const b=e.target.closest('[data-modal]');if(!b)return;modalRoot.innerHTML='';modalRoot.removeEventListener('click',fn);if(b.dataset.modal==='confirmar')onConfirm();};modalRoot.addEventListener('click',fn);}
function setScreen(next){if(!['home','editor','history','settings'].includes(next))return;screen=next;render();window.scrollTo({top:0,behavior:'instant'});}
function refreshEditor(){const y=window.scrollY;render();requestAnimationFrame(()=>window.scrollTo({top:y,behavior:'instant'}));}
function render(){photoRenderToken++;releasePhotoURLs();document.querySelectorAll('[data-nav]').forEach(b=>{const val=b.dataset.nav;b.classList.toggle('active',val===screen);if(b.classList.contains('nav-btn'))b.setAttribute('aria-current',val===screen?'page':'false');});if(screen==='home')app.innerHTML=renderHome();else if(screen==='editor')app.innerHTML=renderEditor();else if(screen==='history')app.innerHTML=renderHistory();else app.innerHTML=renderSettings();if(screen==='editor'&&(step===1||step===4))hydratePhotoCards();}
function renderHome(){const list=[...store.quotes].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));const done=list.filter(q=>q.status!=='draft').length;const sumsMonth=list.filter(q=>q.status!=='draft'&&q.date?.slice(0,7)===nowISO().slice(0,7)).reduce((n,q)=>n+Math.max(0,sums(q).total),0);return `<section class="hero"><div><span class="eyebrow light">Ramon Retoques Automotivos</span><h1>Seu orçamento, mais rápido e profissional.</h1><p>Selecione as peças, descreva os serviços, defina os valores e entregue um PDF com a identidade da oficina.</p><button class="btn btn-primary" data-action="new">${I('plus')} Novo orçamento ${I('arrow')}</button></div><div class="hero-right"><div class="hero-metric"><div><small>Orçamentos registrados</small><strong>${list.length}</strong></div>${I('file')}</div><div class="hero-metric"><div><small>Finalizados / preliminares</small><strong>${done}</strong></div>${I('check')}</div><div class="hero-metric"><div><small>Valor calculado neste mês*</small><strong>${money(sumsMonth)}</strong></div>${I('wallet')}</div></div></section><div class="dashboard-grid"><section class="card card-pad"><div class="list-head"><h2>Orçamentos recentes</h2><button class="btn btn-ghost btn-sm" data-nav="history">Ver todos ${I('arrow')}</button></div>${list.length?list.slice(0,4).map(q=>`<div class="quick-link" data-open="${E(q.id)}" role="button" tabindex="0"><span class="quick-link-icon">${I('file')}</span><span class="quick-link-main"><strong>${E(q.client||'Cliente não informado')}</strong><small>${E(q.vehicle||'Veículo não informado')} · ${E(q.code)} · ${prettyDate(q.date)}</small></span>${statusHTML(q)}<span class="arrow-mini">${I('arrow')}</span></div>`).join(''):`<div class="empty-slab">${I('file')}<p class="mb0">Nenhum orçamento salvo ainda.<br>Comece pelo botão “Novo orçamento”.</p></div>`}</section><aside><div class="card card-pad mb20"><h2 style="font-size:18px">Acesso rápido</h2><div class="btn-group" style="display:grid"><button class="btn btn-secondary btn-block" data-nav="history">${I('list')} Consultar histórico</button><button class="btn btn-secondary btn-block" data-action="backup">${I('download')} Exportar backup</button><button class="btn btn-secondary btn-block" data-nav="settings">${I('settings')} Dados da oficina</button></div></div><div class="tip-panel"><h3>${I('info')} Seus dados ficam neste aparelho</h3><p>Os orçamentos são guardados neste navegador, sem conta ou mensalidade. Faça backups regularmente. Celular e computador não sincronizam nesta versão.</p></div></aside></div><p class="footer-message">* Soma dos valores atualmente informados em orçamentos não classificados como rascunho. Não representa faturamento.</p>`;}
function renderEditor(){const q=activeQuote();const s=sums(q);return `<div class="page-heading"><div><span class="eyebrow">Área de orçamento</span><h1>${step===4?'Revisar orçamento':'Novo orçamento'}</h1><p class="muted">${E(q.code)} <span class="muted">·</span> ${prettyDate(q.date)} <span class="chip">${I('save')} Salvamento local automático</span></p></div><button class="btn btn-secondary btn-sm" data-action="save">${I('save')} Salvar</button></div><div class="steps">${[['Cliente e veículo','Dados'],['Peças e serviços','Seleção'],['Valores','Pagamento'],['Revisar e PDF','Conferência']].map(([title,sub],idx)=>`<button class="step ${step===idx+1?'active':step>idx+1?'done':''}" data-step="${idx+1}" type="button"><span class="step-num">${step>idx+1?I('check'):idx+1}</span><span><span class="step-label">${title}</span><span class="step-sub">${sub}</span></span></button>`).join('')}</div><div class="editor-grid"><section class="card work-panel">${step===1?stepOne(q):step===2?stepTwo(q):step===3?stepThree(q):stepFour(q)}<div class="action-footer">${step>1?`<button class="btn btn-secondary" data-action="previous">${I('back')} Voltar</button>`:`<button class="btn btn-ghost" data-nav="home">${I('back')} Início</button>`}<div class="right">${step<4?`<button class="btn btn-primary" data-action="next">Continuar ${I('arrow')}</button>`:`<button class="btn btn-secondary" data-action="save">${I('save')} Salvar</button><button class="btn btn-primary" data-action="pdf">${I('download')} Gerar PDF</button>`}</div></div></section><aside class="aside-panel"><div class="summary-hero"><div><span class="muted small">${s.pending?'Total informado até agora':'Total do orçamento'}</span><div class="figure">${money(Math.max(0,s.total))}</div><small class="sub-note" style="color:#afb7bf">${s.pending?`${s.pending} valor(es) pendente(s)`:''}</small></div>${I('wallet')}</div><div class="card card-pad"><h3>Resumo do orçamento</h3><div class="summary-row"><span>Peças selecionadas</span><strong>${getSelected(q).length}</strong></div><div class="summary-row"><span>Serviços</span><strong>${money(s.services)}</strong></div><div class="summary-row"><span>Peças / materiais</span><strong>${money(s.materials)}</strong></div><div class="summary-row"><span>Serviços gerais</span><strong>${money(s.extras)}</strong></div><div class="summary-row"><span>Desconto</span><strong>− ${money(s.discount)}</strong></div><div class="summary-row total"><span>Total calculado</span><strong>${money(Math.max(0,s.total))}</strong></div>${s.pending?`<div class="note warning mt16">${I('alert')} <span>${s.pending} valor(es) não informado(s). O PDF será identificado como preliminar.</span></div>`:''}${s.invalid?`<div class="note danger mt16">${I('alert')} <span>O desconto ultrapassa o subtotal informado.</span></div>`:''}<p class="sub-note mt16 mb0">Os preços são definidos por você. Não há preço automático por peça.</p></div></aside></div><div class="footer-message">Dados salvos somente neste navegador. Exporte cópia de segurança no Histórico.</div>`;}
function field(name,label,value,opts={}){const type=opts.type||'text',placeholder=opts.placeholder?`placeholder="${E(opts.placeholder)}"`:'',required=opts.required?'<span class="required"> *</span>':'',max=opts.max?`maxlength="${opts.max}"`:'';return `<div class="field ${opts.cls||''}"><label for="${name}">${E(label)}${required}</label><input id="${name}" data-field="${name}" class="control" type="${type}" ${placeholder} ${max} value="${E(value??'')}" ${opts.inputmode?`inputmode="${opts.inputmode}"`:''}>${opts.help?`<div class="field-help">${E(opts.help)}</div>`:''}</div>`;}
function area(name,label,value,placeholder,opts={}){return `<div class="field ${opts.cls||''}"><label for="${name}">${E(label)}</label><textarea class="control" id="${name}" data-field="${name}" placeholder="${E(placeholder||'')}">${E(value||'')}</textarea></div>`;}
function stepOne(q){return `<header><div class="section-title"><span class="section-icon">${I('car')}</span><h2>Cliente e veículo</h2></div><p>Preencha o necessário para identificar o orçamento. Os campos opcionais podem ficar em branco.</p></header><div class="section-caption">Dados do cliente</div><div class="field-grid">${field('client','Nome do cliente',q.client,{required:true,placeholder:'Nome completo',cls:'span2'})}${field('phone','Telefone / WhatsApp',q.phone,{placeholder:'(31) 99999-9999',inputmode:'tel'})}${field('document','CPF / CNPJ (opcional)',q.document,{placeholder:'Somente se necessário'})}${field('address','Endereço do cliente',q.address,{placeholder:'Rua, bairro, cidade',cls:'span2'})}</div><div class="section-divider"></div><div class="section-caption">Dados do veículo</div><div class="field-grid">${field('vehicle','Veículo / modelo',q.vehicle,{required:true,placeholder:'Ex.: Chevrolet Onix',cls:'span2'})}${field('plate','Placa',q.plate,{placeholder:'ABC1D23 / ABC-1234',max:8})}${field('color','Cor',q.color,{placeholder:'Ex.: Prata'})}${field('year','Ano',q.year,{placeholder:'Ex.: 2020',inputmode:'numeric',max:4})}${field('evaluator','Responsável pela avaliação',q.evaluator,{placeholder:'Nome do profissional'})}${area('vehicleNote','Observações sobre o veículo',q.vehicleNote,'Estado geral, avarias já existentes, etc.',{cls:'span2'})}${photoSection(q)}</div><div class="section-divider"></div><div class="section-caption">Identificação</div><div class="field-grid">${field('date','Data do orçamento',q.date,{type:'date'})}<div class="field"><label>Número local</label><input class="control" value="${E(q.code)}" disabled><div class="field-help">Identificador deste navegador; pode se repetir em outros aparelhos.</div></div></div>`;}
function partCatalogHtml(q,filter=''){const f=filter.toLocaleLowerCase('pt-BR').trim();return GROUPS.map(g=>{const parts=g.parts.filter(p=>p[1].toLocaleLowerCase('pt-BR').includes(f));if(!parts.length)return '';return `<div class="region"><div class="region-head"><h3>${E(g.name)}</h3><small>${parts.length} itens</small></div><div class="part-grid">${parts.map(([id,name])=>{const p=q.items.find(i=>i.id===id);return `<label class="part-check ${p?.selected?'selected':''}"><input aria-label="${E(name)}" type="checkbox" data-part="${E(id)}" ${p?.selected?'checked':''}><span>${E(name)}</span></label>`;}).join('')}</div></div>`;}).join('')||`<div class="empty-slab">Nenhuma peça encontrada.</div>`;}
function selectedCard(i,index){const materialInputDisabled=i.noMaterial?'disabled':'';return `<article class="service-card"><div class="service-card-head"><div class="gap-8"><span class="number">${index+1}</span><strong>${E(i.name)}</strong></div><button class="icon-btn danger" title="Retirar seleção" aria-label="Retirar ${E(i.name)}" data-action="unselect" data-id="${E(i.id)}">${I('close')}</button></div><div class="service-card-body"><span class="field-label">Intervenções <span class="muted" style="font-weight:400">(pode marcar várias)</span></span><div class="chip-grid">${INTERVENTIONS.map(t=>`<button type="button" class="service-chip ${i.interventions.includes(t)?'chosen':''}" data-action="intervention" data-id="${E(i.id)}" data-type="${E(t)}" aria-pressed="${i.interventions.includes(t)}">${i.interventions.includes(t)?'✓ ':''}${E(t)}</button>`).join('')}</div><div class="field mb14"><label for="desc-${E(i.id)}">Descrição do serviço</label><textarea id="desc-${E(i.id)}" data-item="${E(i.id)}" data-item-field="description" class="control" placeholder="Ex.: Recuperar amassado e realizar pintura da peça">${E(i.description)}</textarea></div><div class="field-grid"><div class="field"><label for="svc-${E(i.id)}">Serviços / mão de obra (R$)</label><input id="svc-${E(i.id)}" data-money-item="${E(i.id)}" data-money-field="service" class="control" type="text" inputmode="decimal" placeholder="A definir" value="${E(editMoney(i.service))}"></div><div class="field"><label for="mat-${E(i.id)}">Peças / materiais (R$)</label><input id="mat-${E(i.id)}" data-money-item="${E(i.id)}" data-money-field="material" class="control" type="text" inputmode="decimal" placeholder="${i.noMaterial?'Não se aplica':'A definir'}" value="${E(editMoney(i.material))}" ${materialInputDisabled}><label class="check-inline"><input type="checkbox" data-no-material="${E(i.id)}" ${i.noMaterial?'checked':''}> Sem cobrança de material</label></div></div><div class="field mt16"><label for="obs-${E(i.id)}">Observação da peça (opcional)</label><input id="obs-${E(i.id)}" data-item="${E(i.id)}" data-item-field="observation" class="control" placeholder="Avarias existentes, condições de reparo..." value="${E(i.observation)}"></div></div></article>`;}
function stepTwo(q){const selected=getSelected(q);return `<header><div class="section-title"><span class="section-icon">${I('check')}</span><h2>Peças e serviços</h2></div><p>Marque apenas as partes do veículo que receberão serviços. Em seguida, informe o trabalho e os valores.</p></header><div class="between mb14"><strong>${selected.length} peça(s) selecionada(s)</strong><span class="chip soft-red">Seleção rápida</span></div><div class="search-box mb20">${I('search')}<input id="part-search" class="control" autocomplete="off" placeholder="Buscar peça..." value="${E(searchParts)}"></div><div id="parts-list">${partCatalogHtml(q,searchParts)}</div><div class="section-divider"></div><div class="section-heading"><div><h2>Adicionar peça ou serviço</h2><p class="muted small">Para itens que não estão na lista.</p></div></div><div class="custom-add"><input class="control" id="custom-name" placeholder="Ex.: Maçaneta traseira esquerda" maxlength="100"><button class="btn btn-secondary" data-action="add-custom">${I('plus')} Adicionar</button></div><div class="section-divider"></div><div class="section-heading"><div><h2>Detalhes das peças selecionadas</h2><p class="muted small">A descrição é livre e os valores são informados manualmente.</p></div><span class="chip">${selected.length}</span></div><div class="selected-stack">${selected.length?selected.map((i,n)=>selectedCard(i,n)).join(''):`<div class="empty-slab">${I('check')}<p class="mb0">Marque uma ou mais peças acima para preencher os serviços.</p></div>`}</div><div class="note mt16">${I('info')} <span>Preço em branco significa <strong>“a definir”</strong>. Se não houver cobrança de material, marque a caixa correspondente.</span></div>`;}
function stepThree(q){const s=sums(q);return `<header><div class="section-title"><span class="section-icon">${I('wallet')}</span><h2>Valores e condições</h2></div><p>Confira os subtotais e informe descontos, pagamento e observações do orçamento.</p></header><div class="section-caption">Valores calculados automaticamente</div><div class="money-total"><div class="money-tile"><small>Serviços de peças</small><strong>${money(s.services)}</strong></div><div class="money-tile"><small>Peças e materiais</small><strong>${money(s.materials)}</strong></div><div class="money-tile"><small>Serviços gerais</small><strong>${money(s.extras)}</strong></div><div class="money-tile highlight"><small>Total ${s.pending?'parcial':''}</small><strong id="total-tile">${money(Math.max(0,s.total))}</strong></div></div><div class="section-divider"></div><div class="section-heading"><div><h2>Serviços gerais</h2><p class="muted small">Ex.: polimento completo, higienização, transporte.</p></div><button class="btn btn-secondary btn-sm" data-action="add-extra">${I('plus')} Adicionar</button></div><div id="extras-list">${(q.extras||[]).map((x,i)=>`<div class="extra-row"><div class="field"><label>Descrição</label><input class="control" data-extra="${E(x.id)}" data-extra-field="name" value="${E(x.name)}" placeholder="Nome do serviço"></div><div class="field"><label>Valor (R$)</label><input class="control" data-extra="${E(x.id)}" data-extra-field="value" data-money="1" inputmode="decimal" value="${E(editMoney(x.value))}" placeholder="A definir"></div><button class="icon-btn danger" data-action="remove-extra" data-id="${E(x.id)}" title="Excluir item">${I('trash')}</button></div>`).join('')||'<p class="muted small">Nenhum serviço geral adicionado.</p>'}</div><div class="section-divider"></div><div class="field-grid"><div class="field"><label for="discount">Desconto geral (R$)</label><input class="control" id="discount" data-money-quote="discount" inputmode="decimal" placeholder="0,00" value="${E(editMoney(q.discount))}"></div><div class="field"><label>Total depois do desconto</label><input class="control" id="readonly-total" disabled value="${E(money(Math.max(0,s.total)))}"></div></div>${s.invalid?`<div class="note danger mt16">${I('alert')} <span>O desconto não pode ultrapassar o subtotal. Corrija o valor.</span></div>`:''}<div class="section-divider"></div><div class="section-caption">Formas de pagamento aceitas</div><div class="payment-grid">${PAYMENT_TYPES.map(p=>`<label class="payment-option"><input type="checkbox" data-payment="${E(p)}" ${q.payments.includes(p)?'checked':''}>${E(p)}</label>`).join('')}</div><div class="field-grid mt16">${field('paymentDetails','Parcelamento / condições',q.paymentDetails,{placeholder:'Ex.: até 3x sem juros',cls:'span2'})}<div class="field"><label for="cash-value">Valor à vista (R$) — opcional</label><input class="control" id="cash-value" data-money-quote="cashValue" inputmode="decimal" placeholder="Não informado" value="${E(editMoney(q.cashValue))}"></div><div class="field"><label for="install-value">Valor a prazo (R$) — opcional</label><input class="control" id="install-value" data-money-quote="installmentValue" inputmode="decimal" placeholder="Não informado" value="${E(editMoney(q.installmentValue))}"></div></div><div id="payment-review">${renderPaymentReview(q)}</div><div class="section-divider"></div><div class="field-grid">${field('delivery','Prazo estimado para execução',q.delivery,{placeholder:'Ex.: 5 dias úteis'})}${field('validDays','Validade do orçamento (dias)',q.validDays,{type:'number',inputmode:'numeric',placeholder:'30'})}${area('conditions','Observações e condições',q.conditions,'Informações adicionais do orçamento.',{cls:'span2'})}</div><div class="note mt16">${I('calendar')} <span>Validade até <strong>${prettyDate(plusDays(q.date,q.validDays))}</strong>. Valores à vista e a prazo são alternativas de pagamento e <strong>não</strong> entram novamente na soma.</span></div>`;}
function differentConditions(q){const s=sums(q);return (q.cashValue!==null&&q.cashValue!==s.total)||(q.installmentValue!==null&&q.installmentValue!==s.total);}
function renderPaymentReview(q){if(!differentConditions(q))return '';return `<div class="note warning mt16">${I('alert')} <div><strong>Condições diferentes do total calculado.</strong><div>Confira se os valores à vista ou a prazo estão corretos. Eles serão exibidos como alternativas, sem somar ao total.</div><label class="check-inline"><input type="checkbox" id="paymentReviewed" ${q.paymentReviewed?'checked':''}> Conferi e confirmo essas condições</label></div></div>`;}
function reviewItemTable(q){const rows=[...getSelected(q).map(i=>({name:i.name,desc:[i.interventions.join(', '),i.description].filter(Boolean).join(' · '),svc:i.service,mat:i.noMaterial?0:i.material})),...q.extras.map(x=>({name:'Serviço geral',desc:x.name,svc:x.value,mat:0}))];return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Peça</th><th>Serviço</th><th class="text-right">Mão de obra</th><th class="text-right">Materiais</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="row-title">${E(x.name)}</td><td>${E(x.desc||'—')}</td><td class="amount"><span class="mobile-cell-label">Serviços</span>${E(valueOrDash(x.svc))}</td><td class="amount"><span class="mobile-cell-label">Materiais</span>${E(valueOrDash(x.mat))}</td></tr>`).join('')||'<tr><td colspan="4">Nenhum serviço selecionado.</td></tr>'}</tbody></table></div>`;}
function stepFour(q){const s=sums(q);return `<header><div class="section-title"><span class="section-icon">${I('eye')}</span><h2>Revisar e gerar PDF</h2></div><p>Confira as informações antes de entregar o orçamento ao cliente.</p></header>${s.pending?`<div class="note warning mb20">${I('alert')}<div><strong>Orçamento preliminar</strong><div>${s.pending} campo(s) de valor ainda não informado(s). O PDF indicará claramente que os valores estão pendentes.</div></div></div>`:''}${s.invalid?`<div class="note danger mb20">${I('alert')}O desconto ultrapassa o subtotal. Corrija em Valores e condições.</div>`:''}<section class="review-section"><div class="review-section-head"><h3>Cliente e veículo</h3><button class="btn btn-sm btn-ghost" data-step="1">${I('edit')} Editar</button></div><div class="review-section-body review-two"><div class="review-data"><small>Cliente</small><strong>${E(q.client||'Não informado')}</strong></div><div class="review-data"><small>Telefone</small><strong>${E(q.phone||'—')}</strong></div><div class="review-data"><small>Veículo</small><strong>${E(q.vehicle||'Não informado')}</strong></div><div class="review-data"><small>Placa</small><strong>${E(q.plate||'—')}</strong></div><div class="review-data"><small>Data / validade</small><strong>${prettyDate(q.date)} / ${prettyDate(plusDays(q.date,q.validDays))}</strong></div><div class="review-data"><small>Número</small><strong>${E(q.code)}</strong></div></div></section><section class="review-section"><div class="review-section-head"><h3>Peças e serviços (${getSelected(q).length})</h3><button class="btn btn-sm btn-ghost" data-step="2">${I('edit')} Editar</button></div><div class="review-section-body">${reviewItemTable(q)}</div></section><section class="review-section"><div class="review-section-head"><h3>Pagamento e condições</h3><button class="btn btn-sm btn-ghost" data-step="3">${I('edit')} Editar</button></div><div class="review-section-body review-two"><div class="review-data"><small>Serviços</small><strong>${money(s.services+s.extras)}</strong></div><div class="review-data"><small>Materiais</small><strong>${money(s.materials)}</strong></div><div class="review-data"><small>Desconto</small><strong>${money(s.discount)}</strong></div><div class="review-data"><small>Pagamento</small><strong>${E(q.payments.join(', ')||'Não informado')}</strong></div><div class="review-data"><small>À vista</small><strong>${E(valueOrDash(q.cashValue))}</strong></div><div class="review-data"><small>A prazo</small><strong>${E(valueOrDash(q.installmentValue))}</strong></div></div>${q.conditions?`<div class="review-section-body" style="border-top:1px solid var(--line)"><span class="muted small">Condições: </span>${E(q.conditions)}</div>`:''}</section><div class="review-photo-choice"><div><strong>Fotos do veículo</strong><small>${photoList(q).length} foto(s) registrada(s)</small></div><label class="photo-pdf-choice"><input type="checkbox" data-include-photos ${q.includePhotosInPdf?'checked':''} ${!photoList(q).length?'disabled':''}><span><strong>Incluir fotos no PDF</strong><small>${q.includePhotosInPdf?'As fotos serão acrescentadas ao final do documento.':'PDF somente com informações e valores.'}</small></span></label></div><div class="review-amount"><div><small>${s.pending?'Soma dos valores informados — preliminar':'Total do orçamento'}</small><strong>${money(Math.max(0,s.total))}</strong></div>${statusHTML(q)}</div><div class="btn-group mt16"><button class="btn btn-primary" data-action="pdf">${I('download')} Baixar PDF</button><button class="btn btn-secondary" data-action="share-pdf">${I('share')} Compartilhar PDF</button><button class="btn btn-secondary" data-action="whatsapp">${I('whatsapp')} Mensagem no WhatsApp</button></div><p class="sub-note mt16 mb0">O compartilhamento direto do PDF depende do aparelho. A opção WhatsApp abre uma mensagem, mas não anexa o documento automaticamente.</p>`;}
function renderHistory(){return `<div class="page-heading"><div><span class="eyebrow">Arquivo de orçamentos</span><h1>Histórico</h1><p class="muted">Edite, duplique, gere novamente o PDF ou faça backup dos registros.</p></div><button class="btn btn-primary" data-action="new">${I('plus')} Novo</button></div><div class="card card-pad"><div class="history-toolbar"><div class="search-box">${I('search')}<input class="control" id="history-search" placeholder="Buscar cliente, veículo, placa ou número..." value="${E(historyFilter)}"></div><button class="btn btn-secondary" data-action="backup">${I('download')} Backup</button><button class="btn btn-secondary" data-action="import-trigger">${I('upload')} Importar</button><input type="file" accept=".json,application/json" id="import-file" class="file-hidden"></div><div class="note mb20">${I('info')}<span>Dados exclusivos deste navegador. Para mudar de aparelho ou evitar perdas, exporte e guarde o arquivo de backup.</span></div><div id="history-list" class="history-list">${historyListHtml()}</div></div>`;}
function historyListHtml(){const f=historyFilter.toLocaleLowerCase('pt-BR').trim();const quotes=[...store.quotes].filter(q=>[q.client,q.vehicle,q.plate,q.code].some(v=>String(v||'').toLocaleLowerCase('pt-BR').includes(f))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return quotes.length?quotes.map(q=>{const s=sums(q);return `<article class="card history-item"><div><div class="gap-8 wrap"><span class="tag">${E(q.code)}</span>${statusHTML(q)}</div><div class="record-title">${E(q.client||'Cliente não informado')}</div><div class="record-meta"><span>${I('car')} ${E(q.vehicle||'Veículo não informado')}</span><span>${E(q.plate||'Sem placa')}</span><span>${I('calendar')} ${prettyDate(q.date)}</span></div></div><div><div class="record-amount">${money(Math.max(0,s.total))}${s.pending?'<div class="tiny muted">Valores pendentes</div>':''}</div><div class="actions"><button class="btn btn-secondary btn-sm" data-action="open" data-id="${E(q.id)}">${I('edit')} Editar</button><button class="btn btn-secondary btn-sm" data-action="history-pdf" data-id="${E(q.id)}">${I('download')} PDF</button><button class="icon-btn" title="Duplicar" aria-label="Duplicar" data-action="duplicate" data-id="${E(q.id)}">${I('copy')}</button><button class="icon-btn danger" title="Excluir" aria-label="Excluir" data-action="delete" data-id="${E(q.id)}">${I('trash')}</button></div></div></article>`;}).join(''):`<div class="empty-slab">${I('search')}<p class="mb0">Nenhum orçamento encontrado.</p></div>`;}
function renderSettings(){const c=store.config;return `<div class="page-heading"><div><span class="eyebrow">Personalização</span><h1>Configurações da oficina</h1><p class="muted">Essas informações aparecem no cabeçalho e nos próximos PDFs.</p></div><span class="chip">${I('save')} Salvo automaticamente</span></div><div class="settings-grid"><section class="card card-pad"><div class="section-caption">Identificação comercial</div><div class="field-grid">${configField('name','Nome comercial',c.name,{cls:'span2'})}${configField('responsible','Responsáveis',c.responsible)}${configField('phone','Telefone / WhatsApp',c.phone)}${configField('address','Endereço da oficina',c.address,{cls:'span2'})}</div><div class="section-divider"></div><div class="section-caption">Logo da oficina</div><div class="settings-preview"><img id="settings-logo" alt="Logo configurada" src="${E(c.logo||window.RAMON_LOGO_DATA)}"></div><div class="upload-field"><label for="logo-upload" class="btn btn-secondary">${I('upload')} Trocar imagem</label><input type="file" id="logo-upload" accept="image/png,image/jpeg,image/webp" class="file-hidden"><button class="btn btn-ghost" data-action="restore-logo">Restaurar original</button></div><p class="field-help">A imagem será ajustada automaticamente à área do cabeçalho do PDF, mantendo a proporção e sem cortar ou cobrir textos, inclusive se for quadrada ou vertical.</p><div class="section-divider"></div><div class="section-caption">Condições comerciais</div><div class="field-grid">${configField('validDays','Validade padrão (dias)',c.validDays,{type:'number'})}</div><div class="field mt16"><label>Texto padrão de condições</label><textarea class="control" data-config="conditions">${E(c.conditions)}</textarea></div><div class="field mt16"><label>Frase do rodapé do PDF</label><input class="control" data-config="footer" value="${E(c.footer)}"></div><div class="note mt16">${I('info')} <span>Alterar configurações não modifica automaticamente os dados já preenchidos em orçamentos antigos, mas a logo e a identificação da oficina serão as atuais ao gerar novos PDFs.</span></div></section><aside class="settings-side"><div class="card card-pad mb20"><h3>Seus arquivos</h3><p class="muted small">Tudo fica guardado neste aparelho. Exporte um backup antes de limpar o navegador ou trocar de celular.</p><div class="btn-group" style="display:grid"><button class="btn btn-primary btn-block" data-action="backup">${I('download')} Exportar backup</button><button class="btn btn-secondary btn-block" data-action="settings-import-trigger">${I('upload')} Importar backup</button><input type="file" id="settings-import-file" accept=".json,application/json" class="file-hidden"></div></div><div class="tip-panel"><h3>Versão local gratuita</h3><p>Não utiliza conta, servidor nem mensalidade. Diferentes aparelhos não compartilham os mesmos registros. O acesso aos arquivos deve ser protegido pelo dono do aparelho.</p></div></aside></div>`;}
function configField(name,label,val,opts={}){return `<div class="field ${opts.cls||''}"><label for="config-${name}">${E(label)}</label><input class="control" id="config-${name}" data-config="${name}" type="${opts.type||'text'}" value="${E(val??'')}"></div>`;}
function validateStepOne(q){let good=true;for(const key of ['client','vehicle']){const e=app.querySelector(`[data-field="${key}"]`);if(!q[key]?.trim()){e?.classList.add('error');good=false;}else e?.classList.remove('error');}if(!good)notify('Informe o nome do cliente e o veículo para continuar.');return good;}
function goStep(n){const q=activeQuote();if(step===1&&n>1&&!validateStepOne(q))return;step=Math.min(4,Math.max(1,n));screen='editor';render();window.scrollTo({top:0,behavior:'instant'});}
function validateForPDF(q){const s=sums(q);if(!q.client?.trim()||!q.vehicle?.trim()){notify('Preencha cliente e veículo antes de gerar o PDF.');if(screen==='editor')goStep(1);return false;}if(!s.items){notify('Selecione ao menos uma peça ou serviço geral.');return false;}if(s.invalid){notify('O desconto é maior que o subtotal. Corrija em Valores.');return false;}if(differentConditions(q)&&!q.paymentReviewed){notify('Confirme as diferenças de pagamento na etapa 3.');if(screen==='editor')goStep(3);return false;}return true;}
function fileName(q){const tag=(q.plate||q.client||'Cliente').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'_').slice(0,24);return `Orcamento_Ramon_${tag}_${q.date}_${q.code.replace(/[^a-zA-Z0-9-]/g,'')}.pdf`;}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function makePdf(q,share=false){if(!validateForPDF(q))return;try{const b=app.querySelector('[data-action="pdf"]');if(b){b.disabled=true;b.innerHTML='<span class="spinner"></span> Gerando...';}const include=!!q.includePhotosInPdf&&photoList(q).length>0;const pdfPhotos=[];if(include){for(const item of photoList(q)){const record=await getPhotoFile(item.id);if(!record?.blob)throw new Error('Foto ausente do armazenamento local: '+item.id);pdfPhotos.push({blob:record.blob,width:record.width,height:record.height});}}const pdf=await window.RamonPDF.generate(q,store.config,{money,prettyDate,plusDays,sums,getSelected},pdfPhotos);if(share){const file=new File([pdf],fileName(q),{type:'application/pdf'});if(navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:`Orçamento ${q.code}`});}catch(err){if(err.name!=='AbortError')notify('Não foi possível compartilhar. Use Baixar PDF.');}}else{downloadBlob(pdf,fileName(q));notify('Compartilhamento direto indisponível. PDF baixado para anexar manualmente.');}}else{downloadBlob(pdf,fileName(q));notify('PDF gerado e disponibilizado para download.');}q.status=sums(q).pending?'prelim':'ready';q.updatedAt=new Date().toISOString();persist();if(screen==='editor'||screen==='history')render();}catch(err){console.error('Erro ao gerar PDF:',err);notify(err.message?.includes('Foto ausente')?'Uma foto não foi encontrada. Remova-a ou desmarque a opção de incluir fotos no PDF.':'Não foi possível gerar o PDF. Confira as fotos e tente novamente.');}}
function saveQuote(){const q=activeQuote();const s=sums(q);if(!q.client?.trim()||!q.vehicle?.trim()){notify('Salvo como rascunho. Preencha o cliente e o veículo quando possível.');q.status='draft';}else{q.status=s.pending?'prelim':'ready';notify(s.pending?'Orçamento preliminar salvo.':'Orçamento salvo.');}q.updatedAt=new Date().toISOString();persist();if(screen==='editor')render();}
async function exportBackup(){try{notify('Preparando backup com as fotos…');const images=[];for(const q of store.quotes){for(const photo of photoList(q)){const record=await getPhotoFile(photo.id);if(!record?.blob)throw new Error('Há fotos que não estão disponíveis no navegador.');images.push({id:photo.id,quoteId:q.id,name:photo.name||'',width:record.width,height:record.height,data:await blobAsDataURL(record.blob)});}}const raw=JSON.stringify({version:1,exportedAt:new Date().toISOString(),counter:store.counter,config:store.config,quotes:store.quotes,photos:images});downloadBlob(new Blob([raw],{type:'application/json;charset=utf-8'}),`Backup_Ramon_${nowISO()}.json`);notify(`Backup criado com ${images.length} foto(s). Guarde-o em local seguro.`);}catch(err){notify('Falha no backup: '+(err.message||'verifique as fotos salvas.'));}}
function importedQuote(q){if(!q||typeof q!=='object'||!Array.isArray(q.items))throw Error('Orçamento inválido');const result={...q};const safe=(x,max=4000)=>String(x??'').slice(0,max);['id','code','date','client','phone','address','document','vehicle','plate','color','year','vehicleNote','evaluator','paymentDetails','delivery','conditions','createdAt','updatedAt'].forEach(k=>result[k]=safe(q[k],k==='conditions'?8000:2000));result.status=['draft','prelim','ready'].includes(q.status)?q.status:'draft';result.items=q.items.slice(0,150).map(i=>({id:safe(i.id,100),name:safe(i.name,200),custom:!!i.custom,selected:!!i.selected,interventions:Array.isArray(i.interventions)?i.interventions.filter(x=>INTERVENTIONS.includes(x)):[],description:safe(i.description,10000),manualDescription:!!i.manualDescription,service:Number.isSafeInteger(i.service)&&i.service>=0?i.service:null,material:Number.isSafeInteger(i.material)&&i.material>=0?i.material:null,noMaterial:!!i.noMaterial,observation:safe(i.observation,5000)}));result.extras=Array.isArray(q.extras)?q.extras.slice(0,100).map(x=>({id:safe(x.id,100),name:safe(x.name,200),value:Number.isSafeInteger(x.value)&&x.value>=0?x.value:null})):[];for(const k of ['discount','cashValue','installmentValue'])result[k]=Number.isSafeInteger(q[k])&&q[k]>=0?q[k]:null;result.validDays=Math.max(1,Math.min(365,Number(q.validDays)||30));result.payments=Array.isArray(q.payments)?q.payments.filter(x=>PAYMENT_TYPES.includes(x)):[];result.paymentReviewed=!!q.paymentReviewed;result.photos=Array.isArray(q.photos)?q.photos.slice(0,PHOTO_LIMIT).map(p=>({id:safe(p.id,100),name:safe(p.name,100)})):[];result.includePhotosInPdf=!!q.includePhotosInPdf&&result.photos.length>0;return result;}
async function importBackup(file){if(!file)return;if(file.size>80*1024*1024){notify('Backup muito grande (limite 80 MB).');return;}try{const parsed=JSON.parse(await file.text());if(parsed.version!==1||!Array.isArray(parsed.quotes))throw Error('Formato não reconhecido');if(parsed.quotes.length>2000)throw Error('Quantidade excessiva');const quotes=parsed.quotes.map(importedQuote);if(new Set(quotes.map(q=>q.id)).size!==quotes.length)throw Error('IDs de orçamentos duplicados');const cfg={...defaults(),...(parsed.config&&typeof parsed.config==='object'?parsed.config:{})};for(const k of ['name','responsible','phone','address','conditions','footer'])cfg[k]=String(cfg[k]??'').slice(0,8000);cfg.validDays=Math.max(1,Math.min(365,Number(cfg.validDays)||30));if(cfg.logo&&!(typeof cfg.logo==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(cfg.logo)&&cfg.logo.length<1500000))cfg.logo=null;const images=Array.isArray(parsed.photos)?parsed.photos:[];if(images.length>quotes.length*PHOTO_LIMIT)throw Error('Fotos em excesso');const referenced=new Set(quotes.flatMap(q=>photoList(q).map(p=>p.id)));const ids=new Set();const records=images.map(item=>{if(!item||typeof item.id!=='string'||!referenced.has(item.id)||ids.has(item.id))throw Error('Foto inválida ou duplicada');ids.add(item.id);return {id:item.id,quoteId:String(item.quoteId||''),name:String(item.name||'').slice(0,100),width:Number(item.width)||0,height:Number(item.height)||0,blob:dataURLToBlob(item.data)};});if([...referenced].some(id=>!ids.has(id)))throw Error('Backup sem algumas fotos');confirmDialog('Importar backup',`O arquivo contém ${quotes.length} orçamento(s) e ${records.length} foto(s). A importação substituirá os registros, fotos e configurações deste navegador.`, 'Substituir dados',async()=>{try{await replacePhotoFiles(records);store={version:1,counter:Math.max(Number(parsed.counter)||0,quotes.length),config:cfg,quotes,activeId:null};persist();historyFilter='';setScreen('history');notify('Backup restaurado, incluindo as fotos.');}catch(err){notify('Não foi possível restaurar as fotos. Seus orçamentos atuais foram mantidos.');}},true);}catch(err){notify('Backup inválido ou incompleto. Nenhum dado foi alterado.');}}
function settingsChange(field,value){const c=store.config;if(!Object.prototype.hasOwnProperty.call(c,field))return;if(field==='validDays')c[field]=Math.max(1,Math.min(365,Number(value)||30));else c[field]=String(value).slice(0,8000);persist();}
function formatInputOnBlur(el){const cents=parseMoney(el.value);if(el.value.trim()&&!Number.isInteger(cents)){el.classList.add('error');notify('Valor inválido. Digite, por exemplo, 1.250,50.');return;}el.classList.remove('error');el.value=editMoney(cents);}
function updateSummaryDOM(){if(screen!=='editor')return;const q=activeQuote(),s=sums(q);const hero=app.querySelector('.summary-hero');if(hero){const fig=hero.querySelector('.figure');if(fig)fig.textContent=money(Math.max(0,s.total));const subtitle=hero.querySelector('.small');if(subtitle)subtitle.textContent=s.pending?'Total informado até agora':'Total do orçamento';}const rows=app.querySelectorAll('.aside-panel .summary-row strong');const vals=[String(getSelected(q).length),money(s.services),money(s.materials),money(s.extras),'− '+money(s.discount),money(Math.max(0,s.total))];rows.forEach((e,i)=>{if(vals[i]!=null)e.textContent=vals[i];});const totalInput=app.querySelector('#readonly-total');if(totalInput)totalInput.value=money(Math.max(0,s.total));const totalTile=app.querySelector('#total-tile');if(totalTile)totalTile.textContent=money(Math.max(0,s.total));const payReview=app.querySelector('#payment-review');if(payReview)payReview.innerHTML=renderPaymentReview(q);}
function handleInput(e){const el=e.target;const q=activeQuote(screen==='editor');if(el.id==='part-search'){searchParts=el.value;const slot=app.querySelector('#parts-list');if(slot)slot.innerHTML=partCatalogHtml(q,searchParts);return;}if(el.id==='history-search'){historyFilter=el.value;const slot=app.querySelector('#history-list');if(slot)slot.innerHTML=historyListHtml();return;}if(el.matches('[data-config]')){settingsChange(el.dataset.config,el.value);return;}if(screen!=='editor'||!q)return;if(el.matches('[data-field]')){const k=el.dataset.field;if(Object.prototype.hasOwnProperty.call(q,k)){q[k]=el.value;if(k==='phone'){const end=el.selectionStart;el.value=q.phone=phoneMask(el.value);try{el.setSelectionRange(el.value.length,el.value.length);}catch{}}if(k==='plate'){el.value=q.plate=el.value.toUpperCase().replace(/[^A-Z0-9-]/g,'').slice(0,8);}if(k==='validDays'){q[k]=Math.max(1,Math.min(365,Number(el.value)||30));}if(k==='client'||k==='vehicle')el.classList.remove('error');touch(q);}return;}if(el.matches('[data-item]')){const item=q.items.find(i=>i.id===el.dataset.item);if(item){item[el.dataset.itemField]=el.value;if(el.dataset.itemField==='description')item.manualDescription=true;touch(q);}return;}if(el.matches('[data-money-item]')){const item=q.items.find(i=>i.id===el.dataset.moneyItem);if(item){item[el.dataset.moneyField]=parseMoney(el.value);touch(q);updateSummaryDOM();}return;}if(el.matches('[data-money-quote]')){const field=el.dataset.moneyQuote;q[field]=parseMoney(el.value);q.paymentReviewed=false;touch(q);updateSummaryDOM();return;}if(el.matches('[data-extra]')){const extra=q.extras.find(x=>x.id===el.dataset.extra);if(extra){extra[el.dataset.extraField]=el.dataset.extraField==='value'?parseMoney(el.value):el.value;touch(q);updateSummaryDOM();}return;}}
function handleChange(e){const el=e.target;const q=activeQuote(screen==='editor');if(el.id==='logo-upload'){if(el.files[0])readLogo(el.files[0]);return;}if(el.id==='import-file'||el.id==='settings-import-file'){if(el.files[0])importBackup(el.files[0]);el.value='';return;}if(screen!=='editor'||!q)return;if(el.id==='vehicle-photo-gallery'){const files=[...el.files];el.value='';addVehiclePhotos(files,q);return;}if(el.matches('[data-include-photos]')){q.includePhotosInPdf=el.checked;touch(q);if(step===4)refreshEditor();else{const hint=el.closest('label')?.querySelector('small');if(hint)hint.textContent=q.includePhotosInPdf?'Fotos serão acrescentadas ao final do PDF.':'Deixar desmarcado para enviar apenas o orçamento.';}return;}if(el.matches('[data-part]')){const item=q.items.find(i=>i.id===el.dataset.part);if(item){item.selected=el.checked;touch(q);refreshEditor();}return;}if(el.matches('[data-no-material]')){const item=q.items.find(i=>i.id===el.dataset.noMaterial);if(item){item.noMaterial=el.checked;if(item.noMaterial)item.material=null;touch(q);refreshEditor();}return;}if(el.matches('[data-payment]')){if(el.checked&&!q.payments.includes(el.dataset.payment))q.payments.push(el.dataset.payment);else if(!el.checked)q.payments=q.payments.filter(x=>x!==el.dataset.payment);touch(q);return;}if(el.id==='paymentReviewed'){q.paymentReviewed=el.checked;touch(q);return;}if(el.matches('[data-money-item],[data-money-quote],[data-money="1"]')){formatInputOnBlur(el);updateSummaryDOM();return;}}
function handleFocusOut(e){const el=e.target;if(screen==='editor'&&el.matches('[data-money-item],[data-money-quote],[data-money="1"]'))formatInputOnBlur(el);}
async function readLogo(file){if(!file.type.startsWith('image/')){notify('Escolha uma imagem PNG, JPEG ou WebP.');return;}if(file.size>8*1024*1024){notify('Imagem muito grande. Limite de 8 MB.');return;}try{const src=await new Promise((yes,no)=>{const f=new FileReader();f.onload=()=>yes(f.result);f.onerror=no;f.readAsDataURL(file);});const img=await new Promise((yes,no)=>{const x=new Image();x.onload=()=>yes(x);x.onerror=no;x.src=src;});const ratio=Math.min(1,1100/img.width,600/img.height),c=document.createElement('canvas');c.width=Math.round(img.width*ratio);c.height=Math.round(img.height*ratio);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);store.config.logo=c.toDataURL('image/jpeg',.86);persist();render();notify('Logo atualizada.');}catch(e){notify('Não foi possível carregar a imagem.');}}
async function handleClick(e){const nav=e.target.closest('[data-nav]');if(nav){setScreen(nav.dataset.nav);return;}const stepBtn=e.target.closest('[data-step]');if(stepBtn){goStep(Number(stepBtn.dataset.step));return;}const open=e.target.closest('[data-open]');if(open){store.activeId=open.dataset.open;persist();step=4;setScreen('editor');return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;let q=activeQuote(screen==='editor');if(action==='photo-remove'){const current=q,photoId=id;if(!photoList(current).some(p=>p.id===photoId))return;try{await deletePhotoFile(photoId);current.photos=current.photos.filter(p=>p.id!==photoId);if(!current.photos.length)current.includePhotosInPdf=false;touch(current);refreshPhotoSection(current);notify('Foto removida.');}catch(err){notify('Não foi possível remover esta foto.');}return;}if(action==='new'){newQuote();step=1;searchParts='';setScreen('editor');return;}if(action==='previous'){goStep(step-1);return;}if(action==='next'){goStep(step+1);return;}if(action==='save'){saveQuote();return;}if(action==='pdf'){makePdf(activeQuote());return;}if(action==='share-pdf'){makePdf(activeQuote(),true);return;}if(action==='whatsapp'){const message='Olá! Segue o orçamento solicitado. Vou anexar o documento PDF nesta conversa.';window.open('https://wa.me/?text='+encodeURIComponent(message),'_blank','noopener');notify('Anexe o PDF manualmente à conversa do WhatsApp.');return;}if(action==='intervention'){const it=q.items.find(x=>x.id===id);if(it){const t=b.dataset.type;it.interventions=it.interventions.includes(t)?it.interventions.filter(x=>x!==t):[...it.interventions,t];if(!it.manualDescription)it.description=it.interventions.join(', ');touch(q);refreshEditor();}return;}if(action==='unselect'){const it=q.items.find(x=>x.id===id);if(it){if(it.custom)q.items=q.items.filter(x=>x.id!==id);else it.selected=false;touch(q);refreshEditor();}return;}if(action==='add-custom'){const name=app.querySelector('#custom-name')?.value.trim();if(!name){notify('Digite o nome da peça ou serviço.');return;}q.items.push({...makeItem('custom-'+Date.now()+'-'+Math.random().toString(36).slice(2,5),name.slice(0,100),true),selected:true});touch(q);refreshEditor();notify('Item personalizado adicionado.');return;}if(action==='add-extra'){q.extras.push({id:'x-'+Date.now()+'-'+Math.random().toString(36).slice(2,5),name:'',value:null});touch(q);refreshEditor();return;}if(action==='remove-extra'){q.extras=q.extras.filter(x=>x.id!==id);touch(q);refreshEditor();return;}if(action==='backup'){exportBackup();return;}if(action==='import-trigger'){app.querySelector('#import-file')?.click();return;}if(action==='settings-import-trigger'){app.querySelector('#settings-import-file')?.click();return;}if(action==='restore-logo'){store.config.logo=null;persist();render();notify('Logo original restaurada.');return;}if(action==='open'){store.activeId=id;persist();step=4;setScreen('editor');return;}if(action==='history-pdf'){q=store.quotes.find(x=>x.id===id);if(q)makePdf(q);return;}if(action==='duplicate'){const original=store.quotes.find(x=>x.id===id);if(!original)return;const created=newQuote();const clone=JSON.parse(JSON.stringify(original));const preserved={id:created.id,code:created.code,date:created.date,createdAt:created.createdAt,updatedAt:created.updatedAt,status:'draft'};Object.assign(created,clone,preserved,{photos:[],includePhotosInPdf:false});let missing=0;for(const p of photoList(original)){try{const item=await getPhotoFile(p.id);if(!item?.blob){missing++;continue;}const newId='p-'+Date.now()+'-'+Math.random().toString(36).slice(2,12);await savePhotoFile({...item,id:newId,quoteId:created.id});created.photos.push({id:newId,name:p.name});}catch{missing++;}}created.includePhotosInPdf=!!original.includePhotosInPdf&&created.photos.length>0;persist();step=1;setScreen('editor');notify(missing?'Orçamento duplicado, mas algumas fotos não puderam ser copiadas.':'Orçamento e fotos duplicados.');return;}if(action==='delete'){const selected=store.quotes.find(x=>x.id===id);if(!selected)return;confirmDialog('Excluir orçamento',`Excluir ${selected.code} de ${selected.client||'cliente não informado'}? Esta ação não pode ser desfeita.`, 'Excluir',async ()=>{store.quotes=store.quotes.filter(x=>x.id!==id);if(store.activeId===id)store.activeId=null;persist();render();for(const photo of photoList(selected)){try{await deletePhotoFile(photo.id);}catch{}}notify('Orçamento excluído.');},true);return;}}
app.addEventListener('input',handleInput);
app.addEventListener('change',handleChange);
app.addEventListener('focusout',handleFocusOut);
app.addEventListener('click',handleClick);
app.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-open]')){e.preventDefault();e.target.click();}if(e.key==='Enter'&&e.target.id==='custom-name'){e.preventDefault();app.querySelector('[data-action="add-custom"]')?.click();}});
document.querySelector('.site-header').addEventListener('click',handleClick);
render();
})();
